"""Validate the static site generated by build_site.py in stage-47/site."""

from __future__ import annotations

import json
import re
import subprocess
import sys
import tempfile
import urllib.parse
from pathlib import Path

ROOT = Path(__file__).resolve().parent
SITE = ROOT / "site"

sys.path.insert(0, str(ROOT))
from build_site import CHAPTERS, LANGS, SITE_URL  # noqa: E402

errors: list[str] = []
warnings: list[str] = []
_checked_script_bodies: set[str] = set()


def fail(message: str) -> None:
    errors.append(message)


def node_available() -> bool:
    try:
        subprocess.run(["node", "--version"], capture_output=True, check=True)
        return True
    except (FileNotFoundError, subprocess.CalledProcessError):
        return False


NODE_AVAILABLE = node_available()
if not NODE_AVAILABLE:
    warnings.append("node not found on PATH; skipping inline <script> syntax checks")

CARD_ID_RE = re.compile(r'<article class="stage" id="(stage-(\d+)-(\d+))"')
SCRIPT_RE = re.compile(r"<script([^>]*)>(.*?)</script>", re.DOTALL)
CANONICAL_RE = re.compile(r'<link rel="canonical" href="([^"]+)">')
H1_RE = re.compile(r"<h1>(.*?)</h1>", re.DOTALL)
TITLE_RE = re.compile(r"<title>(.*?)</title>", re.DOTALL)
DESCRIPTION_RE = re.compile(r'<meta name="description" content="([^"]*)">')
HREFLANG_RE = re.compile(r'<link rel="alternate" hreflang="([a-z-]+)" href="([^"]+)">')
JSONLD_RE = re.compile(r'<script type="application/ld\+json">(.*?)</script>', re.DOTALL)
OG_IMAGE_RE = re.compile(r'<meta property="og:image" content="([^"]+)">')


def check_inline_scripts(rel: Path, text: str) -> None:
    if not NODE_AVAILABLE:
        return
    for attrs, body in SCRIPT_RE.findall(text):
        if 'type="application/ld+json"' in attrs or "src=" in attrs or not body.strip():
            continue
        if body in _checked_script_bodies:
            continue
        _checked_script_bodies.add(body)
        with tempfile.NamedTemporaryFile("w", suffix=".js", delete=False) as handle:
            handle.write(body)
            temp_path = handle.name
        try:
            result = subprocess.run(["node", "--check", temp_path], capture_output=True, text=True)
            if result.returncode != 0:
                fail(f"{rel}: inline script failed node --check: {result.stderr.strip()}")
        finally:
            Path(temp_path).unlink(missing_ok=True)


def check_page(path: Path) -> None:
    text = path.read_text()
    rel = path.relative_to(SITE)

    canonicals = CANONICAL_RE.findall(text)
    if len(canonicals) != 1:
        fail(f"{rel}: expected exactly one canonical link, found {len(canonicals)}")

    h1s = H1_RE.findall(text)
    if len(h1s) != 1:
        fail(f"{rel}: expected exactly one <h1>, found {len(h1s)}")

    titles = TITLE_RE.findall(text)
    if len(titles) != 1 or not titles[0].strip():
        fail(f"{rel}: expected exactly one non-empty <title>, found {len(titles)}")

    descriptions = DESCRIPTION_RE.findall(text)
    if len(descriptions) != 1 or not descriptions[0].strip():
        fail(f"{rel}: expected exactly one non-empty meta description, found {len(descriptions)}")

    hreflangs = {lang for lang, _ in HREFLANG_RE.findall(text)}
    if hreflangs != {"en", "vi", "x-default"}:
        fail(f"{rel}: expected hreflang en/vi/x-default, found {sorted(hreflangs)}")

    for match in JSONLD_RE.findall(text):
        try:
            json.loads(match)
        except json.JSONDecodeError as error:
            fail(f"{rel}: invalid JSON-LD ({error})")

    og_images = OG_IMAGE_RE.findall(text)
    if not og_images:
        fail(f"{rel}: missing og:image meta tag")
    for image_url in og_images:
        image_path = SITE / urllib.parse.urlparse(image_url).path.lstrip("/")
        if not image_path.exists():
            fail(f"{rel}: og:image file missing: {image_path.relative_to(SITE)}")

    check_inline_scripts(rel, text)


def sitemap_loc_to_path(loc: str) -> Path:
    parsed_path = urllib.parse.urlparse(loc).path
    if parsed_path.endswith("/"):
        return SITE / parsed_path.lstrip("/") / "index.html"
    return SITE / parsed_path.lstrip("/")


def main() -> None:
    if not SITE.exists():
        fail("site directory does not exist; run build_site.py first")
        report()
        return

    if (SITE / "chapters").exists():
        fail("stale stage-47/site/chapters/ directory found; it should no longer be generated")

    pages_to_check: list[Path] = []
    for page in (SITE / "index.html", SITE / "vi" / "index.html",
                 SITE / "privacy.html", SITE / "vi" / "privacy.html"):
        if page.exists():
            pages_to_check.append(page)
        else:
            fail(f"missing expected page: {page.relative_to(SITE)}")

    chapter_numbers = sorted(c["chapter"] for c in CHAPTERS)
    total_cards = {lang: 0 for lang in LANGS}
    for lang in LANGS:
        lang_dir = SITE if lang == "en" else SITE / "vi"
        chapter_dir = lang_dir / "chapter"
        found = (sorted(int(p.name) for p in chapter_dir.iterdir() if p.is_dir())
                 if chapter_dir.exists() else [])
        if found != chapter_numbers:
            fail(f"{lang}: expected {len(chapter_numbers)} chapter pages, found {len(found)}")
        for number in chapter_numbers:
            page = chapter_dir / str(number) / "index.html"
            if not page.exists():
                fail(f"missing chapter page: {page.relative_to(SITE)}")
                continue
            pages_to_check.append(page)
            text = page.read_text()
            card_ids = CARD_ID_RE.findall(text)
            ids_only = [card_id for card_id, _, _ in card_ids]
            if len(ids_only) != len(set(ids_only)):
                fail(f"{page.relative_to(SITE)}: duplicate stage anchor ids")
            for card_id, chapter_str, _ in card_ids:
                if int(chapter_str) != number:
                    fail(f"{page.relative_to(SITE)}: card id {card_id} chapter mismatch")
            total_cards[lang] += len(card_ids)

    for lang in LANGS:
        if total_cards[lang] != 2006:
            fail(f"{lang} chapter pages: expected 2006 total cards, found {total_cards[lang]}")

    for page in pages_to_check:
        check_page(page)

    robots_path = SITE / "robots.txt"
    if not robots_path.exists():
        fail("robots.txt missing")
    else:
        robots_text = robots_path.read_text()
        if f"Sitemap: {SITE_URL}/sitemap.xml" not in robots_text:
            fail("robots.txt missing Sitemap line")

    sitemap_path = SITE / "sitemap.xml"
    if not sitemap_path.exists():
        fail("sitemap.xml missing")
    else:
        sitemap_text = sitemap_path.read_text()
        locs = re.findall(r"<loc>([^<]+)</loc>", sitemap_text)
        if not locs:
            fail("sitemap.xml has no <loc> entries")
        for loc in locs:
            file_path = sitemap_loc_to_path(loc)
            if not file_path.exists():
                fail(f"sitemap.xml: URL does not map to an existing file: {loc}")

    report()


def report() -> None:
    for warning in warnings:
        print(f"WARNING: {warning}")
    if errors:
        for error in errors:
            print(f"ERROR: {error}")
        print(f"\ncheck_site.py failed with {len(errors)} error(s).")
        sys.exit(1)
    print(f"check_site.py passed ({len(warnings)} warning(s)).")


if __name__ == "__main__":
    main()
